import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"账号与个人信息","description":"","frontmatter":{},"headers":[],"relativePath":"features/accounts.md","filePath":"features/accounts.md"}'),r={name:"features/accounts.md"};function s(c,e,i,l,n,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="账号与个人信息" tabindex="-1">账号与个人信息 <a class="header-anchor" href="#账号与个人信息" aria-label="Permalink to &quot;账号与个人信息&quot;">​</a></h1><p>账号页用于管理后台用户；个人信息页用于当前登录者查看和修改自己的资料。入口分别为 <strong>系统管理 → 用户管理</strong>、头像菜单中的个人信息（<code>/profile</code>）。本版本没有部门或岗位管理流程。</p><h2 id="身份与前置" tabindex="-1">身份与前置 <a class="header-anchor" href="#身份与前置" aria-label="Permalink to &quot;身份与前置&quot;">​</a></h2><p>用户列表需要 <code>system:user:list</code>；详情、新增、编辑、删除分别检查 <code>system:user:query/add/edit/remove</code>。重置密码使用编辑权限。角色选择来自当前身份允许分配的角色；开启租户后，不能凭页面传入的用户 ID 越过服务端租户范围。拥有登录身份不代表拥有用户管理权限。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>用账号、手机或状态筛选列表，点击查询；切换条件后从第一页读取。</li><li>点击新增，填写账号、昵称、联系方式、密码及角色；角色 ID 保持字符串，不手工转成数字。</li><li>编辑时先读取详情中的 <code>user</code> 和 <code>roleIds</code>，确认选中的角色再保存。只读详情不提供保存动作。</li><li>删除或重置密码先阅读确认框。重置返回的临时密码只用于交接，不写入日志或文档，随后让用户修改。</li><li>重新打开详情或刷新列表，确认保存结果；批量表格操作见<a href="/xinghui-admin-vue3/docs/features/bulk.html">用户导入导出</a>。</li></ol><h2 id="字段与接口" tabindex="-1">字段与接口 <a class="header-anchor" href="#字段与接口" aria-label="Permalink to &quot;字段与接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>前端契约</th><th>使用方式</th></tr></thead><tbody><tr><td><code>userId</code></td><td>string</td><td>服务端分配；编辑/删除保持原值</td></tr><tr><td><code>username</code> / <code>nickname</code></td><td>string</td><td>账号与显示名称分别填写</td></tr><tr><td><code>mobile</code> / <code>email</code></td><td>string</td><td>使用自己的合法联系方式，不复制种子信息</td></tr><tr><td><code>status</code></td><td>number</td><td>按页面启停选项提交</td></tr><tr><td><code>roleIds</code></td><td>string[]</td><td>仅选当前允许分配的角色</td></tr><tr><td><code>password</code></td><td>optional string</td><td>新建时填写；不要用空字符串模拟密码重置</td></tr></tbody></table><p>列表为 <code>GET /system/user/list</code>，新建/编辑为 <code>POST /system/user/add</code>、<code>POST /system/user/edit</code>；详情为 <code>GET /system/user/{userId}</code>。删除和重置是携带 <code>userId</code> 查询参数的 POST，请调用现有 API 函数。</p><h2 id="正常结果与恢复" tabindex="-1">正常结果与恢复 <a class="header-anchor" href="#正常结果与恢复" aria-label="Permalink to &quot;正常结果与恢复&quot;">​</a></h2><p>保存成功后应能读回用户及角色；删除成功后列表不再出现该记录。没有动作权限时按钮隐藏或不可用，直接请求仍被拒绝。列表失败时重试；保存失败时保留表单并检查字段提示，不要连续点击生成重复用户。账号/联系方式重复、角色越权等问题应修改数据后再提交；会话失效需要重新登录。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>前端：<code>apps/web-ele/src/views/system/user/index.vue</code>、<code>apps/web-ele/src/api/system/user.ts</code>（<code>UserForm</code>、<code>getUser</code>）。</li><li>后端：<code>system-admin/src/main/java/com/xinghuiTec/controller/SysUserController.java</code>（<code>getUser</code>、<code>addUser</code>、<code>resetPassword</code>）。</li><li>本人页面：<code>apps/web-ele/src/views/_core/profile/personal-profile.vue</code>；权限与租户规则见<a href="/xinghui-admin-vue3/docs/development/tenant-platform.html">身份边界</a>。</li></ul>',13)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
